mapper.select:
SELECT

(
SELECT COUNT(*) FROM car_charge_monitor
WHERE station_id = #{stationId}
AND deleted = 0
AND alarm_status IN ('0', '未告警')
AND monitor_time BETWEEN #{statTimeStart} AND #{statTimeEnd}
) +
(
SELECT COUNT(*) FROM bike_charge_monitor
WHERE station_id = #{stationId}
AND deleted = 0
AND alarm_status IN ('0', '未告警')
AND monitor_time BETWEEN #{statTimeStart} AND #{statTimeEnd}
) +
(
SELECT COUNT(*) FROM share_charge_monitor
WHERE station_id = #{stationId}
AND deleted = 0
AND alarm_status IN ('0', '未告警')
AND monitor_time BETWEEN #{statTimeStart} AND #{statTimeEnd}
) AS normalDeviceNum,


(
SELECT COUNT(*) FROM car_charge_monitor
WHERE station_id = #{stationId}
AND deleted = 0
AND alarm_status NOT IN ('0', '未告警')
AND monitor_time BETWEEN #{statTimeStart} AND #{statTimeEnd}
) +
(
SELECT COUNT(*) FROM bike_charge_monitor
WHERE station_id = #{stationId}
AND deleted = 0
AND alarm_status NOT IN ('0', '未告警')
AND monitor_time BETWEEN #{statTimeStart} AND #{statTimeEnd}
) +
(
SELECT COUNT(*) FROM share_charge_monitor
WHERE station_id = #{stationId}
AND deleted = 0
AND alarm_status NOT IN ('0', '未告警')
AND monitor_time BETWEEN #{statTimeStart} AND #{statTimeEnd}
) AS abnormalDeviceNum

SELECT
SUM(CASE WHEN process_status IN ('1', '2', '待处理', '处理中') THEN 1 ELSE 0 END) AS oilWaitHandleNum, CASE WHEN COUNT(*) = 0 THEN 0
ELSE ROUND(SUM(CASE WHEN process_status IN ('0', '3', '已完成', '已关闭') THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) END AS oilHandleCompleteRate FROM oil_monitor WHERE station_id = #{stationId} AND deleted = 0 AND identify_time BETWEEN #{statTimeStart} AND #{statTimeEnd}
